pub fn sample_exact_with_fixed_const_term (n: u16, const_term: Scalar<E>) -> Self {
    let mut coefficients = vec![const_term];
    for _ in 1..=n {
        coefficients.push(Scalar::random());
    }
    Polynomial::from_coefficients(coefficients)
}

